from __future__ import annotations
from typing import List, Tuple


def bump_base(n: int, old: int, new: int) -> int:
    """Rewrite n hereditarily in base `old`, then read it in base `new`."""
    if n == 0:
        return 0
    digits: List[int] = []
    m = n
    while m > 0:
        digits.append(m % old)
        m //= old
    total = 0
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] != 0:
            total += digits[i] * (new ** bump_base(i, old, new))
    return total


def goodstein(start: int, steps: int) -> List[Tuple[int, int]]:
    """First `steps` (base, value) pairs of the Goodstein sequence from `start`."""
    out: List[Tuple[int, int]] = []
    value, base = start, 2
    for _ in range(steps):
        out.append((base, value))
        if value == 0:
            break
        value = bump_base(value, base, base + 1) - 1
        base += 1
    return out


def main() -> None:
    for base, value in goodstein(4, 8):
        print(f"base {base:>2}: {value}")
    print("Raw values explode, yet the omega-form ordinal strictly descends,")
    print("so by the termination engine the sequence must reach 0.")


if __name__ == "__main__":
    main()

