function CNF_COMPARE(a, b):           # a, b are CNF term lists
    i <- 0
    while i < len(a) and i < len(b):
        (ea, ca) <- a[i]; (eb, cb) <- b[i]
        c <- CNF_COMPARE(ea, eb)       # compare exponents
        if c != 0: return c
        if ca != cb: return sign(ca - cb)
        i <- i + 1
    return sign(len(a) - len(b))

